// Fonts too big for Adafruit GFX (its glyph offsets are int8, so ~128 px is
// the ceiling). Same bitmap packing as GFX (bits run on across rows), wider
// fields. Generated by tools/mkfonts.py ('big' fonts), drawn by Text.cpp.
#pragma once
#include <stdint.h>

#include "fonts/gfxfont_compat.h"

struct BigGlyph {
  uint32_t off;
  uint16_t w, h, adv;
  int16_t xo, yo;  // yo: from the baseline to the glyph's top (negative = above)
};

struct BigFont {
  const uint8_t *bitmap;
  const BigGlyph *glyph;
  uint8_t first, last;
  uint16_t yAdvance;
  int16_t ascent;
};
